class Scale:
    _SHARP_CHROMATIC = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"]
    _FLAT_CHROMATIC = ["C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab", "A", "Bb", "B"]

    # Tonics whose scales are written with flats (major and minor keys).
    # By convention the natural notes "C" and "a" use sharps when ascending.
    _FLAT_TONICS = {"C", "D", "F", "G", "Bb", "Eb", "Ab", "Db", "Gb"}

    _INTERVAL_STEPS = {"m": 1, "M": 2, "A": 3}

    def __init__(self, tonic):
        self.tonic = tonic[0].upper() + tonic[1:]
        base = self._FLAT_CHROMATIC if self.tonic in self._FLAT_TONICS else self._SHARP_CHROMATIC
        start = base.index(self.tonic)
        self._chromatic = base[start:] + base[:start]

    def chromatic(self):
        return list(self._chromatic)

    def interval(self, intervals):
        notes = [self.tonic]
        index = 0
        for interval in intervals:
            index = (index + self._INTERVAL_STEPS[interval]) % 12
            notes.append(self._chromatic[index])
        return notes

